    /** One icon as inline SVG. Unknown names render nothing rather than erroring. */
    public static function svg(string $name, string $class = 'i4'): string
    {
        $paths = self::PATHS[$name] ?? null;

        if ($paths === null) {
            return '';
        }

        return '<svg class="'.e($class).'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.$paths.'</svg>';
    }

    /** The plain head-and-shoulders silhouette used where a teacher photo would go. */
    public static function blankProfile(): string
    {
        return '<svg viewBox="0 0 64 64" fill="currentColor" aria-hidden="true"><circle cx="32" cy="23" r="12.5"/><path d="M7 64c0-14.5 11.2-25 25-25s25 10.5 25 25z"/></svg>';
    }
